(function() {
    'use strict';

    class ThornburyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Transform the Salesforce`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Thornbury Industrial Supplies Ltd.).
            this.BUDGET = 4.5;            // £4.5M / 18-month transformation budget
            this.FULL_SCOPE = 7.8;       // ~£7.8M full scope across all 4 levers (forces sequencing)
            this.EXPOSED = 41;           // ~£41M exposed (£19M mandated + ~£22M mid-market watchers)
            this.BIG_ACCOUNT = 9;        // £9M largest single account, switching clause active
            this.START_ADOPTION = 11;    // 11% website share of orders at start
            this.START_CAP = 19;         // 18 of 95 reps digitally confident (~19/100)
            this.START_RISK = 55;        // latent channel-conflict & margin risk

            // Concept truths (the coordinated, value-based, governed path).
            this.TRUE_THESIS = `coordinated`;
            this.TRUE_COVERAGE = `valuebased`;
            this.TRUE_GOVERNANCE = `pricefloor`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    retained: 0,                 // £M of exposed revenue defended vs status quo
                    adoption: this.START_ADOPTION,
                    capability: this.START_CAP,
                    risk: this.START_RISK,       // channel-conflict & margin risk (lower better)
                    budgetUsed: 0,               // £M of transformation budget committed
                    techStranded: false,         // platform funded, people skipped
                    bigAccountLost: false,       // £9M switching clause triggered
                    pricewar: false,             // marketplace opened without governance
                    retainedHistory: [0],
                    adoptionHistory: [this.START_ADOPTION],
                    capabilityHistory: [this.START_CAP],
                    riskHistory: [this.START_RISK],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean to the classic WRONG plays — a blind
                // click-through must not auto-win (tech-buy, all-equal, unchanged
                // commission, discount-led marketplace, activity report).
                state.decisions = {
                    thesis: `techbuy`,
                    segment: `smallest`,
                    urgency: 50,
                    platform: 1.5,
                    crm: 1.0,
                    reskill: 1.0,
                    inside: 1.0,
                    phase: `techthenlater`,
                    coverage: `alldigital`,
                    commission: `unchanged`,
                    governance: `discount`,
                    redeploy: 50,
                    reallocate: `morefeatures`,
                    account: `selfserve`,
                    case: `activity`,
                    payback: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const th = document.getElementById(`thesisInput`);
                const sg = document.getElementById(`segmentInput`);
                const ur = document.getElementById(`urgencyInput`);
                if (th) decisions.thesis = th.value;
                if (sg) decisions.segment = sg.value;
                if (ur) decisions.urgency = parseInt(ur.value, 10);
                if (!Number.isFinite(decisions.urgency) || decisions.urgency < 0 || decisions.urgency > 100) {
                    warn(`warn_urgency_range`); return false;
                }
            } else if (round === 2) {
                const pl = document.getElementById(`platformInput`);
                const cr = document.getElementById(`crmInput`);
                const rk = document.getElementById(`reskillInput`);
                const ins = document.getElementById(`insideInput`);
                const ph = document.getElementById(`phaseInput`);
                if (pl) decisions.platform = parseFloat(pl.value);
                if (cr) decisions.crm = parseFloat(cr.value);
                if (rk) decisions.reskill = parseFloat(rk.value);
                if (ins) decisions.inside = parseFloat(ins.value);
                if (ph) decisions.phase = ph.value;
                const parts = [decisions.platform, decisions.crm, decisions.reskill, decisions.inside];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.platform + decisions.crm + decisions.reskill + decisions.inside) * 10) / 10;
                if (Math.abs(total - this.BUDGET) > 0.001) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const cv = document.getElementById(`coverageInput`);
                const cm = document.getElementById(`commissionInput`);
                const gv = document.getElementById(`governanceInput`);
                const rd = document.getElementById(`redeployInput`);
                if (cv) decisions.coverage = cv.value;
                if (cm) decisions.commission = cm.value;
                if (gv) decisions.governance = gv.value;
                if (rd) decisions.redeploy = parseInt(rd.value, 10);
                if (!Number.isFinite(decisions.redeploy) || decisions.redeploy < 0 || decisions.redeploy > 100) {
                    warn(`warn_redeploy_range`); return false;
                }
            } else if (round === 4) {
                const re = document.getElementById(`reallocateInput`);
                const ac = document.getElementById(`accountInput`);
                const cs = document.getElementById(`caseInput`);
                const pb = document.getElementById(`paybackInput`);
                if (re) decisions.reallocate = re.value;
                if (ac) decisions.account = ac.value;
                if (cs) decisions.case = cs.value;
                if (pb) decisions.payback = parseInt(pb.value, 10);
                if (!Number.isFinite(decisions.payback) || decisions.payback < 0 || decisions.payback > 100) {
                    warn(`warn_payback_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let retDelta = 0, adoptDelta = 0, capDelta = 0, riskDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // DIAGNOSE — frame the transformation (Common Error 5 vs coordinated change).
                switch (d.thesis) {
                    case `coordinated`: capDelta += 6; riskDelta -= 6; retDelta += 1; coachKey = `coach_r1_coordinated`; break;
                    case `techbuy`: riskDelta += 4; capDelta -= 2; coachKey = `coach_r1_techbuy`; break;
                    case `defend`: riskDelta += 6; adoptDelta -= 1; coachKey = `coach_r1_defend`; break;
                    case `cost`: riskDelta += 8; coachKey = `coach_r1_cost`; break;
                }

                // Name the most exposed segment (deadline-driven mandated + watchers).
                switch (d.segment) {
                    case `mandated`: retDelta += 2; riskDelta -= 4; if (d.thesis === `coordinated`) coachKey = `coach_r1_sharp`; break;
                    case `smallest`: riskDelta += 3; coachKey = `coach_r1_smallest`; break;
                    case `all`: riskDelta += 2; break;
                }

                // Deadline discipline (Decision Tree: soft deadline costs the £9M account).
                if (d.urgency >= 60) { retDelta += 2; riskDelta -= 4; }
                else if (d.urgency <= 25) { retDelta -= 2; riskDelta += 6; coachKey = `coach_r1_softdeadline`; }

                summaryKey = (d.thesis === `coordinated` && d.segment === `mandated`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // PLAN — sequence the £4.5M (Common Error 1: tech-first/people-later).
                spend += d.platform + d.crm + d.reskill + d.inside;

                // Platform funds the mandate; below ~£1.5M punch-out/API don't land in time.
                if (d.platform >= 1.5) { retDelta += 4; adoptDelta += 6; }
                else if (d.platform >= 1.0) { retDelta += 2; adoptDelta += 3; }
                else { retDelta -= 3; riskDelta += 4; }

                // CRM replaces the paper pipeline — modest capability + risk visibility.
                if (d.crm >= 0.8) { capDelta += 3; riskDelta -= 2; }
                else { capDelta -= 1; }

                // Reskilling is what converts platform spend into adoption (the crux).
                if (d.reskill >= 1.0) { capDelta += 10; adoptDelta += 8; }
                else if (d.reskill >= 0.5) { capDelta += 4; adoptDelta += 3; }
                else { capDelta -= 4; adoptDelta -= 4; }

                // Inside-sales / digital channel build — the low-cost reorder route.
                if (d.inside >= 0.8) { adoptDelta += 5; retDelta += 1; }
                else { adoptDelta += 1; }

                // The sequencing penalty: a big platform with starved reskilling strands the tech.
                if (d.platform >= 2.0 && d.reskill <= 0.5) {
                    ds.techStranded = true;
                    adoptDelta -= 10; capDelta -= 6; retDelta -= 4; riskDelta += 6;
                    coachKey = `coach_r2_stranded`;
                } else {
                    switch (d.phase) {
                        case `platformfirst`: retDelta += 3; adoptDelta += 4; capDelta += 4; riskDelta -= 4; coachKey = `coach_r2_platformfirst`; break;
                        case `techthenlater`: adoptDelta -= 4; capDelta -= 3; riskDelta += 4; coachKey = `coach_r2_techthenlater`; break;
                        case `peoplefirst`: retDelta -= 5; riskDelta += 5; coachKey = `coach_r2_peoplefirst`; break;
                    }
                }

                summaryKey = (!ds.techStranded && d.platform >= 1.5 && d.reskill >= 1.0 && d.phase === `platformfirst`) ? `sum_r2_good` :
                             (ds.techStranded ? `sum_r2_stranded` : `sum_r2_weak`);
            } else if (round === 3) {
                // DECIDE — coverage, commission, governance (Common Errors 2, 3, 4).
                switch (d.coverage) {
                    case `valuebased`: retDelta += 5; adoptDelta += 8; riskDelta -= 6; coachKey = `coach_r3_valuebased`; break;
                    case `alldigital`: retDelta -= 6; adoptDelta += 10; riskDelta += 10; coachKey = `coach_r3_alldigital`; break;
                    case `nochange`: adoptDelta -= 6; riskDelta += 4; coachKey = `coach_r3_nochange`; break;
                }

                // Commission redesign — channel-neutral or the plan fights the transformation.
                switch (d.commission) {
                    case `neutral`: adoptDelta += 8; capDelta += 4; riskDelta -= 6; if (d.coverage === `valuebased`) coachKey = `coach_r3_neutral`; break;
                    case `unchanged`: adoptDelta -= 10; riskDelta += 8; coachKey = `coach_r3_commission`; break;
                    case `cut`: capDelta -= 8; riskDelta += 6; adoptDelta -= 2; coachKey = `coach_r3_cut`; break;
                }

                // Channel / marketplace governance — price floor BEFORE opening the channel.
                switch (d.governance) {
                    case `pricefloor`: retDelta += 3; riskDelta -= 8; break;
                    case `discount`: ds.pricewar = true; retDelta -= 5; riskDelta += 12; coachKey = `coach_r3_pricewar`; break;
                    case `nomarket`: riskDelta -= 2; retDelta -= 1; break;
                }

                // Redeploy & coach the 41 resistant reps.
                if (d.redeploy >= 60) { capDelta += 6; adoptDelta += 3; riskDelta -= 3; }
                else if (d.redeploy <= 25) { capDelta -= 5; riskDelta += 5; }

                summaryKey = (d.coverage === `valuebased` && d.commission === `neutral` && d.governance === `pricefloor`) ? `sum_r3_good` :
                             (ds.pricewar ? `sum_r3_pricewar` : `sum_r3_weak`);
            } else if (round === 4) {
                // RECOVER & PROVE ROI (Common Error 5: activity not value).
                switch (d.reallocate) {
                    case `enablement`: adoptDelta += 8; capDelta += 5; retDelta += 3; riskDelta -= 4; coachKey = `coach_r4_enablement`; break;
                    case `morefeatures`: adoptDelta += 1; riskDelta += 3; coachKey = `coach_r4_features`; break;
                    case `discountpush`: ds.pricewar = true; retDelta -= 3; riskDelta += 8; coachKey = `coach_r4_discount`; break;
                }

                // Save (or lose) the wavering £9M account — the deadline made real.
                switch (d.account) {
                    case `taskforce`: retDelta += 6; riskDelta -= 5; capDelta += 2; break;
                    case `selfserve`: ds.bigAccountLost = true; retDelta -= 8; riskDelta += 8; coachKey = `coach_r4_lostaccount`; break;
                    case `wait`: ds.bigAccountLost = true; retDelta -= 9; riskDelta += 6; coachKey = `coach_r4_lostaccount`; break;
                }

                // The board-ready value case (ROI vs activity).
                switch (d.case) {
                    case `roi`: retDelta += 4; riskDelta -= 6; capDelta += 2; if (d.account === `taskforce`) coachKey = `coach_r4_roi`; break;
                    case `activity`: riskDelta += 6; coachKey = `coach_r4_activity`; break;
                    case `vision`: riskDelta += 4; coachKey = `coach_r4_vision`; break;
                }

                if (d.payback >= 60) { retDelta += 2; riskDelta -= 3; }
                else if (d.payback <= 25) { retDelta -= 2; riskDelta += 4; }

                summaryKey = (d.case === `roi` && d.account === `taskforce` && !ds.bigAccountLost) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: the £4.5M transformation budget is metered (Round 2 commits it).
            ds.budgetUsed = Math.min(this.BUDGET, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas with clamps. Retained capped at the exposed pool (£41M).
            ds.retained = Math.max(-this.BIG_ACCOUNT, Math.min(this.EXPOSED, Math.round((ds.retained + retDelta) * 10) / 10));
            ds.adoption = Math.max(0, Math.min(100, Math.round(ds.adoption + adoptDelta)));
            ds.capability = Math.max(0, Math.min(100, Math.round(ds.capability + capDelta)));
            ds.risk = Math.max(0, Math.min(100, Math.round(ds.risk + riskDelta)));

            ds.retainedHistory.push(ds.retained);
            ds.adoptionHistory.push(ds.adoption);
            ds.capabilityHistory.push(ds.capability);
            ds.riskHistory.push(ds.risk);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook actually reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                retained: ds.retained,
                retDelta: Math.round(retDelta * 10) / 10,
                adoption: ds.adoption,
                adoptDelta: Math.round(adoptDelta),
                capability: ds.capability,
                capDelta: Math.round(capDelta),
                risk: ds.risk,
                riskDelta: Math.round(riskDelta),
                budgetUsed: ds.budgetUsed,
                techStranded: ds.techStranded,
                bigAccountLost: ds.bigAccountLost,
                pricewar: ds.pricewar,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg,
                score: _score,
                overallScore: _score
            };
        }

        _fmtMoney(v) {
            // Locale-aware GBP: English "£4.5M" (symbol before), Spanish "4,5 M£" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M£`;
            }
            return `${sign}£${abs.toFixed(1)}M`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`revDisplay`, `domainState.retained`, (v) => {
                const card = document.querySelector(`.thornsim-card-rev`);
                if (card) {
                    card.classList.toggle(`thornsim-rev-positive`, Number(v) > 0.05);
                    card.classList.toggle(`thornsim-rev-negative`, Number(v) < -0.05);
                }
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`adoptDisplay`, `domainState.adoption`, (v) => Math.round(Number(v)) + `%`);
            uiManager.bind(`capDisplay`, `domainState.capability`, (v) => Math.round(Number(v)));
            uiManager.bind(`riskDisplay`, `domainState.risk`, (v) => {
                const card = document.querySelector(`.thornsim-card-risk`);
                if (card) {
                    card.classList.toggle(`thornsim-risk-high`, Number(v) >= 60);
                    card.classList.toggle(`thornsim-risk-low`, Number(v) <= 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET);
            });

            // Round 1 — deadline urgency slider readout.
            const ur = document.getElementById(`urgencyInput`);
            const urReadout = document.getElementById(`urgencyReadout`);
            if (ur && urReadout) {
                urReadout.textContent = ur.value;
                ur.addEventListener(`input`, function() { urReadout.textContent = ur.value; });
            }

            // Round 3 — redeployment slider readout.
            const rd = document.getElementById(`redeployInput`);
            const rdReadout = document.getElementById(`redeployReadout`);
            if (rd && rdReadout) {
                rdReadout.textContent = rd.value;
                rd.addEventListener(`input`, function() { rdReadout.textContent = rd.value; });
            }

            // Round 2 — live budget total (must hit £4.5M).
            const allocIds = [`platformInput`, `crmInput`, `reskillInput`, `insideInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = total.toFixed(1);
                const bar = document.querySelector(`.thornsim-alloc-readout`);
                if (bar) bar.style.color = (Math.abs(total - self.BUDGET) > 0.001) ? `#b23b2e` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

