        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const retScore = Math.max(0, Math.min(100, (ds.retained / this.EXPOSED) * 100));
            const adoption = Math.round(ds.adoption);
            const capability = Math.round(ds.capability);
            const risk = Math.round(ds.risk);
            return Math.round(retScore * 0.34 + adoption * 0.24 + capability * 0.20 + (100 - risk) * 0.22);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const retained = ds.retained;
            const adoption = Math.round(ds.adoption);
            const capability = Math.round(ds.capability);
            const risk = Math.round(ds.risk);

            // Composite extracted to _composite() so the persisted per-period score and this
            // completion summary are identical by construction (v1.1.0).
            const composite = this._composite(ds);

            const defended = retained >= 12 && !ds.bigAccountLost;
            const adopted = adoption >= 35;
            const capable = capability >= 55;
            const failed = ds.techStranded || ds.bigAccountLost || ds.pricewar || risk >= 70;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_stalled`;
            if (defended && adopted && capable && composite >= 75) tierKey = `grade_delivered`;
            else if (defended && capable) tierKey = `grade_mandatemet`;
            else if (ds.techStranded) tierKey = `grade_stranded`;
            else if (ds.bigAccountLost) tierKey = `grade_accountlost`;
            else if (ds.pricewar) tierKey = `grade_pricewar`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (defended && adopted && capable) insights.push(window.mySimulation.t(`insight_delivered`));
            else if (ds.techStranded) insights.push(window.mySimulation.t(`insight_stranded`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.bigAccountLost) insights.push(window.mySimulation.t(`insight_account`));
            if (ds.pricewar) insights.push(window.mySimulation.t(`insight_pricewar`));
            if (capability < 45) insights.push(window.mySimulation.t(`insight_capability`));
            if (adoption < 25) insights.push(window.mySimulation.t(`insight_adoption`));
            if (defended && risk <= 30) insights.push(window.mySimulation.t(`insight_governed`));

            return {
                retained: retained,
                adoption: adoption,
                capability: capability,
                risk: risk,
                defended: defended,
                adopted: adopted,
                capable: capable,
                failed: failed,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="thorn-cm"><p class="thorn-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="thorn-cm-chip ` + (ok ? `thorn-cm-ok` : `thorn-cm-no`) + `">` +
                `<span class="thorn-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="thorn-cm-kpi"><div class="thorn-cm-kpi-val">` + val +
                `</div><div class="thorn-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="thorn-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="thorn-cm">` +
  `<div class="thorn-cm-head">` +
    `<div class="thorn-cm-score"><div class="thorn-cm-score-num">` + Math.round(s.composite) +
       `<span class="thorn-cm-score-den">/100</span></div>` +
       `<div class="thorn-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="thorn-cm-verdict"><div class="thorn-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="thorn-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="thorn-cm-chips">` + chip(!!s.defended, t(`cm_t_defended`)) + chip(!!s.adopted, t(`cm_t_adopted`)) +
      chip(!!s.capable, t(`cm_t_capable`)) + chip(!s.failed, t(`cm_t_governed`)) + `</div></div>` +
  `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="thorn-cm-kpis">` +
      kpi(t(`rev_label`), this._fmtMoney(Number(s.retained)), t(`cm_sub_retained`)) +
      kpi(t(`adopt_label`), Math.round(Number(s.adoption)) + `%`, t(`cm_sub_adoption`)) +
      kpi(t(`cap_label`), Math.round(s.capability), t(`cm_sub_capability`)) +
      kpi(t(`risk_label`), Math.round(s.risk), t(`cm_sub_risk`)) +
    `</div></div>` +
  (insights ? `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="thorn-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

