            if (ds.pricewar) return window.mySimulation.t(`hint_pricewar`);
            if (ds.bigAccountLost) return window.mySimulation.t(`hint_account`);
            if (state.currentPeriod >= 3 && ds.adoption < 20) return window.mySimulation.t(`hint_adoption`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.retained >= 15 && ds.adoption >= 35 && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

